import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const REQUIRED_KINDS = ["w9", "insurance_certificate", "contract"] as const;

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Creates a draft vendor and uploads one document per required kind, waiting for each to be extracted. */
async function createDraftVendorWithExtractedDocuments(member: APIRequestContext): Promise<string> {
  const suffix = uniqueSuffix();
  const vendor = await expectStatus<{ id: string; status: string }>(
    await member.post("/api/vendors", {
      data: {
        name: `REV01 Vendor ${suffix}`,
        category: "services",
        contact_email: `rev01-${suffix}@example.test`,
      },
    }),
    201,
  );
  expect(vendor.status).toBe("draft");

  for (const kind of REQUIRED_KINDS) {
    const document = await expectStatus<{ id: string }>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: `${kind}-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% REV-01 fixture\n"),
          },
        },
      }),
      201,
    );

    await expect
      .poll(
        async () =>
          (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
        { timeout: 60_000, intervals: [500] },
      )
      .toBe("extracted");
  }

  return vendor.id;
}

test.describe("review vendors", () => {
  test(
    "submitting a vendor with all documents extracted moves it to in_review and records an audit event",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorId = await createDraftVendorWithExtractedDocuments(member);

      // Act
      const submitResponse = await member.post(`/api/vendors/${vendorId}/submit`);

      // Assert
      const vendor = await expectStatus<{ id: string; status: string }>(submitResponse, 200);
      expect(vendor.id).toBe(vendorId);
      expect(vendor.status).toBe("in_review");

      const audit = await expectStatus<{ items: Array<{ action: string }> }>(
        await member.get(`/api/vendors/${vendorId}/audit`),
        200,
      );
      expect(audit.items.map((event) => event.action)).toContain("vendor.submitted");
    },
  );
});
